function bindEdit(){$("#tag-box").select2({ajax:{url:BASE_URI+"tag",data:function(a){return{keywords:a.term,page:a.page||1}},processResults:function(a){return{results:(a=a.data).data.map(a=>({id:a.id,text:a.name})),pagination:{more:a.paging.more}}}}}),$('[data-type="upload_file"]').upload({url:BASE_URI+"post/upload",name:"file",template:"{url}",onafter:function(a,t){return 200==a.code?t.prev("input").val(a.data):302===a.code&&(location.href=a.url),!1}})}